#include <sys/wait.h>

namespace {

void printUsage(std::ostream& output) {
    output << "Usage: simp [--verbose] [--trace-parser] [--dump-ast] [--dump-symbols] "
              "[--check-only] [--emit-llvm FILE] [-o FILE] <source.simp>\n";
}

std::string shellQuote(const std::string& value) {
    std::string quoted = "'";
    for (const char character : value) {
        if (character == '\'') {
            quoted += "'\\''";
        } else {
            quoted.push_back(character);
        }
    }
    quoted.push_back('\'');
    return quoted;
}

void writeFile(const std::string& path, const std::string& contents) {
    const std::filesystem::path destination(path);
    if (!destination.parent_path().empty()) {
        std::filesystem::create_directories(destination.parent_path());
    }
    std::ofstream output(path);
    if (!output) {
        throw std::runtime_error("cannot write LLVM IR file: " + path);
    }
    output << contents;
    if (!output) {
        throw std::runtime_error("failed while writing LLVM IR file: " + path);
    }
}

int buildExecutable(const std::string& irPath, const std::string& outputPath) {
    const auto parent = std::filesystem::path(outputPath).parent_path();
    if (!parent.empty()) {
        std::filesystem::create_directories(parent);
    }
    const std::string command = shellQuote(SIMP_CLANG_EXECUTABLE) +
                                " -Wno-override-module -x ir " + shellQuote(irPath) +
                                " -o " + shellQuote(outputPath);
    const int status = std::system(command.c_str());
    if (status == -1) {
        std::cerr << "simp: could not start clang\n";
        return 1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        const int exitCode = WIFEXITED(status) ? WEXITSTATUS(status) : 128;
        std::cerr << "simp: clang failed to compile generated LLVM IR (exit status "
                  << exitCode << ")\n";
        return 1;
    }
    return 0;
}

} // namespace

int main(int argc, char** argv) {
    bool verbose = false;
    bool traceParser = false;
    bool dump = false;
    bool dumpSymbols = false;
    bool checkOnly = false;
    std::string requestedOutput;
    std::string irOutput;
    std::string inputPath;

    for (int index = 1; index < argc; ++index) {
        const std::string argument = argv[index];
        if (argument == "--help" || argument == "-h") {
            printUsage(std::cout);
            return 0;
        }
        if (argument == "--verbose" || argument == "-v") {
            verbose = true;
        } else if (argument == "--trace-parser") {
            traceParser = true;
        } else if (argument == "--dump-ast") {
            dump = true;
        } else if (argument == "--dump-symbols") {
            dumpSymbols = true;
        } else if (argument == "--check-only") {
            checkOnly = true;
        } else if (argument == "-o" || argument == "--emit-llvm") {
            if (index + 1 >= argc) {
                std::cerr << "simp: " << argument << " requires a file path\n";
                return 2;
            }
            if (argument == "-o") {
                requestedOutput = argv[++index];
            } else {
                irOutput = argv[++index];
            }
        } else if (!argument.empty() && argument.front() == '-') {
            std::cerr << "simp: unknown option: " << argument << '\n';
            printUsage(std::cerr);
            return 2;
        } else if (inputPath.empty()) {
            inputPath = argument;
        } else {
            std::cerr << "simp: only one input file is supported in this prototype\n";
            return 2;
        }
    }

    if (inputPath.empty()) {
        printUsage(std::cerr);
        return 2;
    }
    std::ifstream input(inputPath);
    if (!input) {
        std::cerr << "simp: cannot open input file: " << inputPath << '\n';
        return 2;
    }
    const std::string source((std::istreambuf_iterator<char>(input)),
                             std::istreambuf_iterator<char>());

    std::string temporaryIr;
    try {
        simp::Lexer lexer(source, inputPath);
        auto tokens = lexer.tokenize();
        if (verbose) {
            std::cerr << "[verbose] lexed " << (tokens.size() - 1) << " tokens\n";
        }
        simp::Parser parser(std::move(tokens), traceParser ? &std::cerr : nullptr);
        const auto program = parser.parseProgram();
        simp::SemanticAnalyzer semanticAnalyzer;
        semanticAnalyzer.analyze(program);
        if (dump) {
            simp::dumpAst(program, std::cout);
        }
        if (dumpSymbols) {
            semanticAnalyzer.dumpSymbolTable(std::cout);
        }
        if (checkOnly) {
            if (verbose) {
                std::cerr << "[verbose] semantic analysis succeeded; code generation skipped\n";
            }
            return 0;
        }

        simp::CodeGenerator codeGenerator(SIMP_TARGET_TRIPLE);
        const auto ir = codeGenerator.generate(program);
        if (irOutput.empty()) {
            auto outputPath = requestedOutput;
            if (outputPath.empty()) {
                auto name = std::filesystem::path(inputPath).stem().string();
                if (name.empty()) {
                    name = "a.out";
                }
                outputPath = (std::filesystem::path(SIMP_DEFAULT_OUTPUT_DIRECTORY) / name).string();
            }
            temporaryIr = outputPath + ".simp.tmp.ll";
            writeFile(temporaryIr, ir);
            if (buildExecutable(temporaryIr, outputPath) != 0) {
                std::error_code ignored;
                std::filesystem::remove(temporaryIr, ignored);
                return 1;
            }
        } else {
            writeFile(irOutput, ir);
            auto outputPath = requestedOutput;
            if (outputPath.empty()) {
                auto name = std::filesystem::path(inputPath).stem().string();
                if (name.empty()) {
                    name = "a.out";
                }
                outputPath = (std::filesystem::path(SIMP_DEFAULT_OUTPUT_DIRECTORY) / name).string();
            }
            if (buildExecutable(irOutput, outputPath) != 0) {
                return 1;
            }
        }
        if (!temporaryIr.empty()) {
            std::error_code ignored;
            std::filesystem::remove(temporaryIr, ignored);
        }
        if (verbose) {
            std::cerr << "[verbose] semantic analysis succeeded; LLVM IR compiled by clang\n";
        } else if (!dump && !dumpSymbols) {
            const auto outputPath = requestedOutput.empty()
                                        ? (std::filesystem::path(SIMP_DEFAULT_OUTPUT_DIRECTORY) /
                                           std::filesystem::path(inputPath).stem()).string()
                                        : requestedOutput;
            std::cout << "simp: built " << outputPath << '\n';
        }
    } catch (const simp::DiagnosticError& diagnostic) {
        std::cerr << diagnostic.what() << '\n';
        return 1;
    } catch (const std::exception& error) {
        std::cerr << "simp: " << error.what() << '\n';
        if (!temporaryIr.empty()) {
            std::error_code ignored;
            std::filesystem::remove(temporaryIr, ignored);
        }
        return 1;
    }
    return 0;
}
